-- 승인 전 적용 금지. 구간별 격자만 저장하고 최신 관할 이력을 읽어 자동 소속 계산.
-- 과거 jurisdiction_events / grid_events / grid_assign / sections 는 변경하지 않음.
-- 4km 확대는 포함하지 않음. 기존 1km 샘플링 기준 유지.
begin;
do $$ begin
  if (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid='private.grid_effective()'::regprocedure)<>'f22ed69246381504eea6e0d415891a96' then
    raise exception 'grid_effective changed since review';
  end if;
  if to_regprocedure('private.section_owners()') is not null then
    raise exception 'section_owners already exists; review before replacing';
  end if;
  if (select md5(string_agg(id||':'||coords::text,E'\n' order by id)) from public.sections)<>'e451469dec94c4dd421780f27f157801' then
    raise exception 'Section geometry differs from reviewed seed';
  end if;
end $$;
create table private.section_grid(
  section_id text not null references public.sections(id) deferrable initially deferred,
  nx int not null check(nx between 1 and 149),
  ny int not null check(ny between 1 and 253),
  primary key(section_id,nx,ny)
);
alter table private.section_grid enable row level security;
revoke all on private.section_grid from public,anon,authenticated,service_role;
insert into private.section_grid(section_id,nx,ny)
