-- 검토용: 기존 관할/격자 이력은 수정하거나 지우지 않는다.
-- 현재 구간 소속 = 기본 소속 + 유효한 마지막 move 이력.
create or replace function private.section_owners()
returns table(section_id text, branch_id text)
language sql stable security definer set search_path = ''
as $$
  with moves as (
    select e.id, x.sid,
      case e.payload->>'to' when '10' then 'B060' when '11' then 'B061' else e.payload->>'to' end as dest
    from public.jurisdiction_events e
    cross join lateral jsonb_array_elements_text(
      case when jsonb_typeof(e.payload->'sections')='array' then e.payload->'sections' else '[]'::jsonb end
    ) x(sid)
    where e.kind='move'
  ), last_move as (
    select distinct on(m.sid) m.sid,m.dest
    from moves m where m.dest='NONE' or exists(select 1 from public.branches b where b.id=m.dest)
    order by m.sid,m.id desc
  )
  select s.id,case when l.sid is null then s.owner_id else nullif(l.dest,'NONE') end
  from public.sections s left join last_move l on l.sid=s.id
$$;
revoke all on function private.section_owners() from public,anon,authenticated,service_role;

create or replace function private.grid_effective()
returns table(nx int,ny int,branch_id text)
language sql stable security definer set search_path = ''
as $$
  with ev as (
    select e.id,e.kind='cellAdd' as inc,coalesce(e.payload->>'to',e.payload->>'from') as b,
      (c.value->>0)::int as nx,(c.value->>1)::int as ny
    from public.grid_events e,jsonb_array_elements(e.payload->'cells') c
    where e.kind in ('cellAdd','cellRemove') and jsonb_typeof(e.payload->'cells')='array'
  ), last as (
    select distinct on(ev.nx,ev.ny,ev.b) ev.nx,ev.ny,ev.b,ev.inc
    from ev order by ev.nx,ev.ny,ev.b,ev.id desc
  ), auto as (
    select distinct g.nx,g.ny,s.branch_id
    from private.section_grid g join private.section_owners() s on s.section_id=g.section_id
    where s.branch_id is not null
  ), eff as (
    select g.nx,g.ny,g.branch_id from auto g
    where not exists(select 1 from last l where l.nx=g.nx and l.ny=g.ny and l.b=g.branch_id and not l.inc)
    union select l.nx,l.ny,l.b from last l where l.inc
  )
  select eff.nx,eff.ny,eff.branch_id from eff
  join public.branches b on b.id=eff.branch_id and b.status<>'closed'
  join public.hqs h on h.id=b.hq_id and not coalesce(h.is_private,false)
  where eff.nx between 1 and 149 and eff.ny between 1 and 253
$$;
revoke all on function private.grid_effective() from public,anon,authenticated,service_role;

-- 신규 좌표는 다음 단기예보 발표의 정기 수집부터 채워진다.
-- 기존 발표의 cells 순서를 바꾸면 시간별 배열과 좌표가 어긋나므로 변경 금지.
commit;
